/*
 * ForgeUI User Event Hooks
 *
 * LIVE STUDIO FIRMWARE:
 * This file may be regenerated by ForgeUI Studio while designing,
 * building and flashing the internal ESP32-P4 test firmware.
 *
 * STANDALONE EXPORT:
 * After manually exporting a project to C:\ForgeUI-Exports,
 * the exported copy becomes developer-owned.
 *
 * Add GPIO, I/O, hardware actions and application behaviour to
 * the exported project's 95_UserEvents.c file.
 *
 * Do not place permanent product logic in the live Studio firmware copy.
 */

#include "95_UserEvents.h"
#include "90_Studio_Export.h"
#include "96_Hardware_Example_01.h"
#include <stdio.h>

void FG_On_Indicator1_Changed(bool enabled)
{
    printf("[ForgeUI User Event] Indicator1 changed: %s\n",
           enabled ? "ON" : "OFF");
}

void FG_On_Indicator2_Changed(bool enabled)
{
    printf("[ForgeUI User Event] Indicator2 changed: %s\n",
           enabled ? "ON" : "OFF");
}

void FG_On_LED1_Toggle_Changed(bool checked)
{
    fg_hardware_example_01_set_led1(checked);
    printf("[ForgeUI User Event] LED1 Toggle changed: %s\n",
           checked ? "ON" : "OFF");
}

void FG_On_LED2_Toggle_Changed(bool checked)
{
    fg_hardware_example_01_set_led2(checked);
    printf("[ForgeUI User Event] LED2 Toggle changed: %s\n",
           checked ? "ON" : "OFF");
}
